export function applyExplicit_frameBytes(dst: Uint8ClampedArray): void {
  if (dst.length !== W * H * 4) {
    throw new Error(`Expected dst length ${W * H * 4}, got ${dst.length}`);
  }
  dst.set(FRAME_BYTES);
}
